import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []

    try:
        for record in reader:
            if record and any(value.strip() for value in record):
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    def header_score(record):
        if len(record) != expected_width:
            return -1
        nonempty = [value.strip() for value in record if value.strip()]
        if not nonempty:
            return -1
        textual = sum(bool(re.search(r"[A-Za-z]", value)) for value in nonempty)
        unique = len({value.casefold() for value in nonempty})
        return textual + unique / expected_width

    candidates = [
        (header_score(record), index)
        for index, record in enumerate(records)
        if header_score(record) >= 0
    ]
    if candidates:
        best_score = max(score for score, _ in candidates)
        header_index = next(index for score, index in candidates if score == best_score)
    else:
        header_index = 0

    def fit_width(record):
        values = list(record)
        if len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        return values

    columns = fit_width(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = [fit_width(record) for record in records[header_index + 1:]]
    return {"columns": columns, "rows": rows}
